def design(x, k, extra=False):
    j = (k + 1) % 4
    cols = [np.ones(len(x)), *x.T, x[:, k] ** 3, x[:, k] * x[:, j]]
    if extra:
        cols += [x[:, a] * x[:, d] for a in range(4) for d in range(a, 4) if (a, d) != tuple(sorted((k, j)))]
    return np.column_stack(cols)
